SELECT WHERE e.user_id = #{userId} AND e.deleted_at IS NULL AND (e.subscription_id IS NULL OR s.enabled = 1) AND (e.kind <> 'task' OR t.id IS NOT NULL) AND ((e.rrule IS NOT NULL AND e.start_at < #{to}) OR (e.rrule IS NULL AND e.start_at < #{to} AND e.end_at > #{from}))
AND e.kind IN #{kind}
AND COALESCE(e.list_id, t.list_id) IN #{listId}
ORDER BY e.start_at, e.id LIMIT 501

